import{_ as o,a0 as s,w as p,s as u,ao as n,I as a,x as i,a1 as r,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"成功舉辦黑客馬拉松的 10 步指南 | LCTT x X-CMD","titleTemplate":false,"description":"成功舉辦黑客馬拉松的 10 步指南 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"成功舉辦黑客馬拉松的 10 步指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"成功舉辦黑客馬拉松的 10 步指南 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230213.1 ⭐️⭐️⭐️ A 10-step guide for a successful hackathon","title":"成功舉辦黑客馬拉松的 10 步指南","tag":"202309","desc":""},"relativePath":"202309/20230213.1 ⭐️⭐️⭐️ A 10-step guide for a successful hackathon.md","filePath":"[post].md"}'),d={name:"202309/20230213.1 ⭐️⭐️⭐️ A 10-step guide for a successful hackathon.md"};function h(f,l,b,m,T,k){const t=s("Link");return p(),u("div",null,[l[43]||(l[43]=n('<h1 id="成功舉辦黑客馬拉松的-10-步指南" tabindex="-1">成功舉辦黑客馬拉松的 10 步指南 <a class="header-anchor" href="#成功舉辦黑客馬拉松的-10-步指南" aria-label="Permalink to “成功舉辦黑客馬拉松的 10 步指南”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/11/091824uz1hs6l2c16s662r.jpg" alt=""></p><blockquote><p>想要規劃、主辦及管理一次成功的黑客馬拉松，請遵循以下藍圖。</p></blockquote><p>初看起來，<ruby>黑客馬拉松<rt>hackathon</rt></ruby>是很簡單的事情。你需要為它投入多少準備呢？僅設置一個日期，人們便會自動參與。然而，實際上並非如此！</p><p>雖然你可以依靠這種方式碰碰運氣，但實際情況是，黑客馬拉松是科技行業中的基石體驗，參與者都有自己的期待。不僅如此，你的組織也有特定的需求，並應該為黑客馬拉松設定目標。那麼，你應該如何保障黑客馬拉松對你的組織和參與者都有益呢？</p><p>成功的黑客馬拉松，取決於一系列可能會反覆出現的決定。關於你想達成什麼目標的決定，將影響你使用哪些資源以及採用何種溝通方式。這些決定將影響你是選擇線上還是線下進行，而這個決定又將反過來影響你需要的資源以及如何溝通。對齊黑客馬拉松的計劃並非只是讓人們達成共識那麼簡單。你需要一整套內在的決策來達成一致。例如，一場技術難度較高的黑客馬拉松可能無法吸引大量觀眾（你可以問我怎麼知道！），並需要一種需要特殊資源的招募策略。</p><p>這些年來，我主辦過很多次黑客馬拉松，包括最近幾個月中，在我所在的組織主辦的一次黑客馬拉松，由此催生了我們將融入到我們的開源產品 Traefik Proxy 3.0 下一版本中的新特性。因此，相信我，策劃一個能豐富參與者體驗，同時為你的項目創造有價值成果的黑客馬拉松，不僅僅需要期待、披薩，和混亂！</p><p>本文以最近的 Traefik Labs 黑客馬拉松為藍圖。我分享了一個清單，提供了一些技巧和竅門，幫你確定目標，規劃比賽，管理報酬，分享你的成果，以及處理黑客馬拉松的長期效應（黑客馬拉松結束後的工作並未結束！）</p><p>這個指南充當了你規劃最佳實踐的模板，讓你也能成功舉辦一場有大量目標受眾並能帶來實效的黑客馬拉松！</p><h3 id="_1、確定目標的三個問題" tabindex="-1">1、確定目標的三個問題 <a class="header-anchor" href="#_1、確定目標的三個問題" aria-label="Permalink to “1、確定目標的三個問題”">​</a></h3><p>首要且至關重要的步驟就是設定你的目標。這可不簡單，設立目標前你需要在多個方面進行內部整合，提出如下問題：</p><ul><li>你為何想舉辦一場黑客馬拉松？</li><li>你期望誰來參加？</li><li>你將如何衡量你的成功程度？</li></ul><h4 id="確定你的內部利益相關者並設立期望" tabindex="-1">確定你的內部利益相關者並設立期望 <a class="header-anchor" href="#確定你的內部利益相關者並設立期望" aria-label="Permalink to “確定你的內部利益相關者並設立期望”">​</a></h4><p><strong>黑客馬拉松涉及到多個功能部門</strong>。沒有一個黑客馬拉松是由一個社區人員獨自進行的。確保每個人對目標的理解、實現這些目標所需的要求相互呼應，以及必要的資源能得到投入，這些都是重要的。聽起來可能有點過於“公司化”，但即使在最小的項目中，這些功能也是必不可少的。一個項目需要廣泛的接受度和代碼支持。它還需要根據使用者的來做出價值判斷。當然，無論何種項目都需要熱情的貢獻者。</p><p><strong>黑客馬拉松需要跨各功能部門的資源投入</strong>。單一團隊擁有的一整套資源並不能成功地運行一場黑客馬拉松。組織必須投放各種資源，包括：</p><ul><li>市場營銷部門進行規劃和拓展。</li><li>產品管理部門提供產品和行業特定的洞察。</li><li>工程部門提供深度的技術知識和社區參與。</li></ul><p>出於這些原因，黑客馬拉松通常會支持滿足跨功能部門的目標。例如，你的社區團隊可能希望建立歸屬感並將用户轉變為活躍的社區成員。營銷團隊可能希望提高知名度並吸引新用户。工程團隊可能需要特定需求或挑戰的新視角。產品團隊可能對社區應該知道的目標或禁止行為有特定的設想。</p><p>最後但同樣重要的點，黑客馬拉松的預算也需要各部門共同承擔。很抱歉告訴你，黑客馬拉松並非天上掉下來的！你最大的支出始終是你團隊成員的用心投入。</p><h3 id="_2、你為什麼要這麼做" tabindex="-1">2、你為什麼要這麼做？ <a class="header-anchor" href="#_2、你為什麼要這麼做" aria-label="Permalink to “2、你為什麼要這麼做？”">​</a></h3><p>設定你的目標是舉辦成功黑客馬拉松的核心部分。如果你對自己想要做什麼或黑客馬拉松為何重要都不清楚的話，最好情況下，它會浪費大量的潛力；最糟情況下，它將會變成一團混亂。</p><p>社區以歸屬感為動力。你需要決定自己期望從社區得到什麼以及你希望社區成員擁有哪些歸屬感。如果沒有清楚的理解這些，你的黑客馬拉松可能無法最大程度地賦權於你的社區。</p><p>你需要特別關注你的黑客馬拉松的設計和目標。不同類型的黑客馬拉松吸引了不同技能水平的人。如果你期待的代碼很深奧，那麼花費額外的時間來傾聽合適的受眾，並認識到這樣會降低整體的參與度。如果你期待的貢獻在技能和經驗上可以變化，那麼你可能需要拓寬接納的範圍。</p><h4 id="你是否舉辦黑客馬拉松來獲取代碼並推進你的項目" tabindex="-1">你是否舉辦黑客馬拉松來獲取代碼並推進你的項目？ <a class="header-anchor" href="#你是否舉辦黑客馬拉松來獲取代碼並推進你的項目" aria-label="Permalink to “你是否舉辦黑客馬拉松來獲取代碼並推進你的項目？”">​</a></h4><ul><li>有時，項目處於關鍵時刻或者圍繞它有很多興奮點，你希望利用這股力量共同創造一些事情。黑客馬拉松正是一個達成這個目標的好方式！</li><li>如果你擁有一個活躍的用户社區，黑客馬拉松可以將每個人同一時間共聚一堂，以此激發團隊的創造能量。</li></ul><p><strong>注意</strong>：較小的，彼此互相關聯並共享項目經驗的團隊確實更易實現這一目標。你還需要仔細評估構建你的項目所需的技能.</p><h4 id="你舉辦黑客馬拉松的目的是建設你的社區或者重新喚起他們的熱情嗎" tabindex="-1">你舉辦黑客馬拉松的目的是建設你的社區或者重新喚起他們的熱情嗎？ <a class="header-anchor" href="#你舉辦黑客馬拉松的目的是建設你的社區或者重新喚起他們的熱情嗎" aria-label="Permalink to “你舉辦黑客馬拉松的目的是建設你的社區或者重新喚起他們的熱情嗎？”">​</a></h4><ul><li>可能你正在建設你的社區，或者你注意到你的社區需要一些新的活力。黑客馬拉松帶有激動人心的氛圍，它們可以幫助恢復這種活躍度。</li><li>正如我在上文所説，“社區是以歸屬感為動力的。” 如果社區成員感覺他們在這個社區中沒有足夠的歸屬感，或是他們的需求和聲音沒有被重視，他們將會漸漸疏離。這在項目逐步擴大並更加正式化時往往會發生。隨着參與的門檻不斷提高，社區成員歸屬感的下降，項目對用户而言就更像是一種產品。提高社區參與感的一種方式是，舉辦引入用户並降低參與門檻的活動：比如錯誤修復活動、輕型需求、及長期的活動時間線。</li><li>或許正如你的用户社區在壯大，但由於技術日益複雜，與之相應的貢獻者社區也變得更為專業化。在這種情況下，你需要吸引理解你的技術和使用者的複雜技術領域的人才。你應該尋找那些在工作中使用你技術的社區成員 —— 尤其在有大型或複雜部署的公司。這些人更有可能理解用户的需求以及技術本身的要求。他們也會對重大且有價值的優化提出建議。</li><li>你可以選擇那些能建設你的社區，同時符合你的團隊和社區成員的能量和時間的目標。例如，對於 Traefik Labs 來説，一個面向熱心人士的、需要較小時間投入的黑客馬拉松可能會針對我們的插件目錄。然而，當我們在尋找較大貢獻或是需要深度專業知識的貢獻者時，我們可能會關注高級技術人才 —— 特別是我們認識的人。</li></ul><h4 id="你是以慶祝某個事情為目的來舉辦黑客馬拉松嗎" tabindex="-1">你是以慶祝某個事情為目的來舉辦黑客馬拉松嗎？ <a class="header-anchor" href="#你是以慶祝某個事情為目的來舉辦黑客馬拉松嗎" aria-label="Permalink to “你是以慶祝某個事情為目的來舉辦黑客馬拉松嗎？”">​</a></h4>',28)),a("ul",null,[a("li",null,[l[1]||(l[1]=i("黑客馬拉松是慶祝新產品發佈和激發社區熱情的有效方式。例如，這正是我們舉辦 ",-1)),r(t,{href:"https://traefik.io/blog/announcing-traefik-proxy-3-0-hackaethon/"},{default:e(()=>[...l[0]||(l[0]=[i("Traefik Proxy 3.0 Hackaethon",-1)])]),_:1}),l[2]||(l[2]=i(" 的原因。",-1))]),a("li",null,[l[4]||(l[4]=i("黑客馬拉松也適合推廣新產品的功能。在此，",-1)),r(t,{href:"https://traefik.io/blog/announcing-the-inaugural-traefik-hackaethon-2020-in-october/"},{default:e(()=>[...l[3]||(l[3]=[i("Traefik Plugin Hackaethon",-1)])]),_:1}),l[5]||(l[5]=i(" 便是一個很好的例子。",-1))]),a("li",null,[l[7]||(l[7]=i("或許你想要舉辦一個活動來紀念你的頂級貢獻者。那就用黑客馬拉松來做吧！瞧瞧 ",-1)),r(t,{href:"https://www.youtube.com/watch?v=9VZCD9TirCg&list=PLxhvVyxYRvibM_KJBPtPsfEcjnP5oGS8H"},{default:e(()=>[...l[6]||(l[6]=[i("HackerOne 組織的這場黑客馬拉松",-1)])]),_:1}),l[8]||(l[8]=i(" 吧。如果你在思索：“但這並非與開源軟件相關，這怎麼能算是黑客馬拉松呢？”我要告訴你的消息是 —— 黑客馬拉松不只是為了開源軟件！黑客馬拉松是為了與廣大的社區共創。",-1))])]),l[44]||(l[44]=n('<h4 id="你是為了提升知名度而舉辦黑客馬拉松嗎" tabindex="-1">你是為了提升知名度而舉辦黑客馬拉松嗎？ <a class="header-anchor" href="#你是為了提升知名度而舉辦黑客馬拉松嗎" aria-label="Permalink to “你是為了提升知名度而舉辦黑客馬拉松嗎？”">​</a></h4><p>如果你剛起步並想提高你的產品/品牌知名度，黑客馬拉松無疑是個好的開端。然而，請注意一些條件。</p><ul><li>在這個階段，期望目標高度集中或收到大貢獻是不太可能的。你應追求更廣泛而温和的焦點，並儘量減少參與者所需的工作。</li><li>嘗試接觸新的社區成員、經驗相對較少的用户，以及對你特定項目接觸不多的用户。</li></ul><h4 id="你是為了與用户建立聯繫而舉辦黑客馬拉松嗎" tabindex="-1">你是為了與用户建立聯繫而舉辦黑客馬拉松嗎？ <a class="header-anchor" href="#你是為了與用户建立聯繫而舉辦黑客馬拉松嗎" aria-label="Permalink to “你是為了與用户建立聯繫而舉辦黑客馬拉松嗎？”">​</a></h4><p>我認為沒有比舉辦黑客馬拉松更好的辦法來將新用户引入你的項目。用户不僅會對你的項目有深入的瞭解，黑客馬拉松也具有一種獨特的方式，能夠營造出一種難以通過其它類型活動實現的歸屬感。</p><h3 id="_3、你的目標觀眾是誰" tabindex="-1">3、你的目標觀眾是誰？ <a class="header-anchor" href="#_3、你的目標觀眾是誰" aria-label="Permalink to “3、你的目標觀眾是誰？”">​</a></h3><p>假設你已經確定為何要舉辦黑客馬拉松以及你期望實現的目標，那麼接下來該評估參與者需要具備哪些特性才能成功了。根據你設定的目標，明確你的目標受眾，搞清楚哪一類社區成員能幫你實現這些目標。你可以根據以下幾個對比進行考慮：</p><ul><li>高級技能 vs. 混合技能 vs. 初級技能</li><li>專門技能 vs. 廣泛技能</li><li>高強度時間投入 vs. 低強度時間投入</li><li>個人貢獻 vs. 團隊貢獻</li></ul><p>你最活躍的社區成員應該在某種程度上與你的目標觀眾有所呼應。</p><p>如果你能吸引到的觀眾和你的目標觀眾至少有 80% 的不符合，你可能需要重新考慮你的目標。準確識別你的目標受眾對於構築你的黑客馬拉松及相關溝通策略，並讓你的黑客馬拉松更加成功極其重要。</p><h3 id="_4、你計劃如何衡量目標的實現程度" tabindex="-1">4、你計劃如何衡量目標的實現程度？ <a class="header-anchor" href="#_4、你計劃如何衡量目標的實現程度" aria-label="Permalink to “4、你計劃如何衡量目標的實現程度？”">​</a></h3><p>很好，你已經回答了前兩個重大問題並明確了你的目標，接下來要考慮的是第三個重大問題 —— 你打算如何評估目標的實現程度？激勵內部團隊與社區一同構建你的項目的未來，激發歸屬感和提升參與度，這些都十分重要，但你無法斷定成功與否，如果你沒有評估目標的方法。</p><h4 id="活動結束後-什麼標誌着成功" tabindex="-1">活動結束後，什麼標誌着成功？ <a class="header-anchor" href="#活動結束後-什麼標誌着成功" aria-label="Permalink to “活動結束後，什麼標誌着成功？”">​</a></h4><ul><li>顯然，首要的成功標誌是你的參與者整體獲得良好的體驗，並且願意更加積極地參與你的項目。</li><li>如果你在尋求擴大影響力，你可以設定一個參與者人數的目標，並且設定一個在活動後或三個月後再次參與的人數目標。 <ul><li>成功的一大標誌是參與者是否在黑客馬拉松期間互相連接、交互、共享知識，並組建團隊。</li><li>是否形成了指導關係？通過合作，是否有許多新的用户轉變為熟練的中級用户，或者中級用户升級為專家級用户？這是成功的關鍵標誌。</li><li>你的合作機構（比如大學）是否要求在未來舉辦更多的黑客馬拉松或其他活動？</li></ul></li><li>如果你在提升知名度，也可以關注活動後的討論情況。有誰寫了Blog文章？參與者在社交媒體上談論了嗎？</li><li>如果你在尋找貢獻，貢獻是否在你預期範圍內？這些是你需要的貢獻嗎？它們是否影響了你的團隊對問題的思維方式？你會和這些貢獻者建立持久的合作關係嗎？</li></ul><h4 id="活動過後三個月-什麼標誌着成功" tabindex="-1">活動過後三個月，什麼標誌着成功？ <a class="header-anchor" href="#活動過後三個月-什麼標誌着成功" aria-label="Permalink to “活動過後三個月，什麼標誌着成功？”">​</a></h4><p>設定長期成功的基準也同樣重要。以下是可能顯示長期成功的一些例子：</p><ul><li>你的黑客馬拉松應當增多持續為你的項目做出貢獻的人。目標在於讓人們對你的項目保持熱情。如果新來的人從黑客馬拉松開始並保留下來成為用户，或者你的現有用户變得更加活躍，你就算贏了。</li><li>黑客馬拉松作為單獨的事件很棒，但作為營銷內容，它更具價值。這些活動在社區中建立了信任，彰顯了你的反應以及你重視社區的投入。它們運營的趣味性成為了社區成員的聚焦點，並激發他們對未來的期待。人們喜歡看到他人被慶祝，並計劃在將來取得這種成績。</li><li>當你圍繞你的黑客馬拉松製作營銷內容時（或最好，別人為你的黑客馬拉松製作內容），你就可以擴大你在二度聯繫人羣中的影響力。</li><li>以羨慕他人為恥的現象是令人遺憾的。黑客馬拉松是個絕佳的機會，可以邀請那些表現傑出的參與者去做更酷的事情，並宣傳你的項目。</li></ul><h3 id="_5、決定是線下活動還是線上活動" tabindex="-1">5、決定是線下活動還是線上活動 <a class="header-anchor" href="#_5、決定是線下活動還是線上活動" aria-label="Permalink to “5、決定是線下活動還是線上活動”">​</a></h3><p>我猜你可能在思考 —— 線下活動是否還在我們的選擇範圍內？在後疫情時代，我們已經習慣於線上進行所有活動。那麼，線下活動的時代就此結束了嗎？我會爭論説，不，線下活動依然在。只要我們採取適當的防護措施，線下活動仍然是黑客馬拉松的精髓。（LCTT 譯註：此文發表於半年前。）</p><ul><li>線下活動意味着無干擾、豐富的披薩，以及充足的能量飲料激發的友誼。</li><li>線下活動更傾向於促進團隊參與，而不僅僅是個人蔘與。</li><li>線下活動無論規模大小都適應：對大規模羣體組織線下活動會帶來高能量和獎勵。但這會造成較高的成本。如果你計劃舉辦大規模黑客馬拉松，相對經驗較少的開發者（如學生、社團、新入職者）將是更好的目標，因為這些人有更多的時間，並且在展示他們的技能和熱情時有着更大的收穫。</li><li>線下活動也很適合小的團隊，非常適合緊張的計劃和迭代 —— 和新老朋友一起度過的長夜，通常是吃着食物和喝着啤酒！</li></ul><p>當然，雖然線下黑客馬拉松有很多優勢，但這並不是説線上體驗只有缺點。誠然，沒有什麼能替代深夜聚會佐以披薩，即興的評論讓你改變整個項目方向，以及你正在測試或調試時，一雙友好的眼睛注視着你的感覺。然而...</p><ul><li>線上活動意味你可以吸引更廣泛的參與者羣體，且成本大幅減低。</li><li>線上活動尊重殘障人士。</li><li>線上活動不受地理位置約束。</li><li>線上活動為個人做出更多貢獻提供了更大可能。</li><li>線上活動在活動形式和時間長度上提供了更多靈活性 —— 畢竟你不能辦一個持續一個月的線下活動！</li></ul><h4 id="線上黑客馬拉松的時間安排" tabindex="-1">線上黑客馬拉松的時間安排 <a class="header-anchor" href="#線上黑客馬拉松的時間安排" aria-label="Permalink to “線上黑客馬拉松的時間安排”">​</a></h4>',23)),a("p",null,[l[10]||(l[10]=i("決定舉辦線上黑客馬拉松了？很好！現在你需要確定你期望的線上黑客馬拉松類型。你是想要一個持續時間長的還是一個強度大的？請記住，你選擇的 ",-1)),r(t,{href:"https://opensource.com/article/20/8/virtual-hackathon"},{default:e(()=>[...l[9]||(l[9]=[i("線上黑客馬拉松",-1)])]),_:1}),l[11]||(l[11]=i(" 的類型會在某種程度決定你的目標觀眾和溝通策略。",-1))]),l[45]||(l[45]=n('<p><strong>延長的時間線：</strong></p><ul><li>允許參與者在工作之外的時間投入，因此開發者可以不請假就參加。</li><li>提供更多時間來徵求貢獻。</li><li>對於組織者和參與者都需要較少的資源投入。</li><li>延長的時間線需要較少的實時資源。</li></ul><p><strong>緊湊的時間線：</strong></p><ul><li>重現了那種在線下黑客馬拉松中通常體驗到的緊張感。</li><li>在短時間內需要大量的資源。</li><li>需要嚴格的管理和溝通平台。</li><li>需要清晰的一對一溝通，但也可以促進羣體對羣體或社區內部的溝通。</li></ul><h3 id="_6、構築你的溝通策略" tabindex="-1">6、構築你的溝通策略 <a class="header-anchor" href="#_6、構築你的溝通策略" aria-label="Permalink to “6、構築你的溝通策略”">​</a></h3>',5)),a("p",null,[l[14]||(l[14]=i("談及溝通，確定了目標後，你需要決定",-1)),l[15]||(l[15]=a("strong",null,"誰",-1)),l[16]||(l[16]=i("將與參與者溝通以及",-1)),l[17]||(l[17]=a("strong",null,"如何",-1)),l[18]||(l[18]=i("進行溝通。通常，我們需要在流行應用中進行選擇。你的選擇將對活動的氛圍產生影響。不同的 ",-1)),r(t,{href:"https://opensource.com/alternatives/slack"},{default:e(()=>[...l[12]||(l[12]=[i("聊天應用",-1)])]),_:1}),l[19]||(l[19]=i(" 和 ",-1)),r(t,{href:"https://opensource.com/article/21/9/alternatives-zoom"},{default:e(()=>[...l[13]||(l[13]=[i("協作平台",-1)])]),_:1}),l[20]||(l[20]=i(" 都具有各自的文化和優勢。你在初期關於如何舉辦你的黑客馬拉松（線下或線上，長期或緊湊）的決策，可能會對你的溝通策略產生最顯著的影響。",-1))]),l[46]||(l[46]=n('<h4 id="線下溝通計劃" tabindex="-1">線下溝通計劃 <a class="header-anchor" href="#線下溝通計劃" aria-label="Permalink to “線下溝通計劃”">​</a></h4><p>如果你正在舉辦一個線下的黑客馬拉松，可以將其視為一個重要的活動 —— 它幾乎感覺如同一場會議。線下的黑客馬拉松通常包括以下活動：</p><ul><li><strong>研討會 / 圓桌討論</strong>：意在教育並建立面對當前需求的新一代標準 / 最佳實踐。這些環節可以作為 6 至 10 人間的限時討論，他們會一致同意研究結果並向所有參與者公開記錄的內容。</li><li><strong>規劃會議</strong>：常用於產出非編程類的項目，比如制定更新標準。</li><li><strong>編程會議</strong>：用於需要持續工作以持續進步的編程類項目。</li></ul><p>以上每一環節都有各自的溝通需求：</p><ul><li>有人準備來引導，但不主導研討會中的對話。</li><li>記錄者以及確保筆記整理為可發佈內容的人。</li><li>對於研討會： <ul><li>項目經理來保證所有工作的執行。</li><li>管理活動的通用溝通（如食物、清潔、資源管理）。</li><li>主持人負責推動活動議程。</li></ul></li></ul><p>要完成所有這一切，需求來自於你的社區，產品經理和技術團隊的資源和專門知識。從過去的經驗來看，，要管理如此規模的活動，需要一個由社區成員和員工組成的團隊。為了成功，你的團隊將需要專業特長的人員。</p><p>你還需要決定你想要鼓勵的溝通類型，以及誰應該負責：</p><ul><li>多個團隊可能需要輪班以提供全方位的支持。</li><li>開發者關係團隊、工程或支持團隊需負責管理與參與者和中間環節之間的技術溝通。</li><li>社區團隊通常會花費很多時間建立與參與者的聯繫，以幫助他們強化技能或觀點，這也是確保黑客馬拉松魔力的一種方式。</li><li>社區團隊還需要支持市場營銷活動，以吸引參與者並進行後續管理。</li></ul><h4 id="線上溝通方案" tabindex="-1">線上溝通方案 <a class="header-anchor" href="#線上溝通方案" aria-label="Permalink to “線上溝通方案”">​</a></h4><p>對於網絡虛擬的黑客馬拉松，選擇溝通平台主要取決於你想實現的目標，你為黑客馬拉松選擇的時間表（延長或密集），以及你希望促進的溝通方式（同步或異步）。</p><p><strong>在 Git 主機上使用拉取請求和議題（異步）：</strong></p><ul><li>選擇通過 Git 拉取請求和你項目的議題進行交流，可以把對項目的討論保留在你當前的流程中，讓你的團隊更專注響應，而不用自發去引導溝通，這將會節省技術團隊的資源。</li><li>如果你的黑客馬拉松團隊規模較小，或者預期的貢獻相對較少，且你沒有計劃協助參與者組建團隊，那麼這種方式非常合適。</li><li>對於持續時間較長的黑客馬拉松，使用已有的流程尤其有益，因為它們不需要額外的管理，也不需要你的團隊去監控另外的應用。</li><li>然而，缺點在於你只是促進了已經協同工作的個別貢獻者或貢獻者團隊的溝通。連接孤立工作的參與者比較困難，參與者們自行尋找彼此也不容易，這就失去了黑客馬拉松參與者在公開的討論中自發交流的魅力。</li></ul><p><strong>使用聊天應用（同步）：</strong></p><ul><li>選擇專用聊天服務器對於密集型的黑客馬拉松是必須的。</li><li>聊天促進了團隊的組建和對於有快速時間線的複雜項目必要的溝通，並激發了在做出了一些很棒的貢獻前的頭腦風暴。</li><li>再者，你的目標是要建立社區。人們想要加入一個他們可以有歸屬感、有朋友、感到舒適的社區。如果你希望他們長期留存，給參與者提供一個可以相互聯繫的地方是必要的。</li><li>事件結束後聊天服務器依然存在，可以持續促進社區的參與活動。</li></ul><p>不論你選取哪一個平台，你都需要一個溝通方案來確定你的團隊每個人何時在線。管理一個線上黑客馬拉松可能會有點複雜，主要是因為不同的時區的問題 —— 人們可以在任何他們想要的時間、任何他們想要的地方參加。你必須計劃安排在所有時區的人和每一個場合的參與者。排列好一個計劃，清楚在下列情況下誰負責以及何時負責：</p><ul><li>確定響應 SLA。</li><li>活躍你的虛擬空間（一個死氣沉沉的空間會導致溝通質量降低）。</li><li>鼓勵團隊建設。</li><li>解答技術問題。</li><li>查詢參與者的進度。</li><li>檢查空間以確保參與者的安全。</li></ul><h3 id="_7、確定獎項" tabindex="-1">7、確定獎項 <a class="header-anchor" href="#_7、確定獎項" aria-label="Permalink to “7、確定獎項”">​</a></h3><p>你的黑客馬拉松是一個競賽形式的活動嗎？通常，黑客馬拉松的參與者對於優秀貢獻者能獲得大獎和豐富的禮品會感到非常滿意。但在你決定這些令人興奮的獎勵（實物獎品）之前，你必須確定你的競賽所重視的價值。</p>',18)),a("ul",null,[l[24]||(l[24]=a("li",null,"是什麼因素讓一個貢獻變得更出色？如果你的參與者瞭解你對此的態度，他們可能更有可能全力以赴。",-1)),l[25]||(l[25]=a("li",null,"你重視什麼？這是你向參與者闡明你希望看到什麼樣的參賽作品的機會，你可以通過把獎品掛在它旁邊來做到這一點。例如，在上次的 Traefik 黑客馬拉松中，我們為最受歡迎的特性提供了獎賞，實際上，這些特性確實是大多數人最努力的部分。",-1)),l[26]||(l[26]=a("li",null,"參賽作品是否有不同的分類？你需要為每個分類都設定獎項。",-1)),a("li",null,[l[22]||(l[22]=i("創造一個評分標準（定義和排名成績的表格或網格，",-1)),r(t,{href:"https://www.isothermal.edu/about/assessment/assets/rubric-present.pdf"},{default:e(()=>[...l[21]||(l[21]=[i("像這個例子",-1)])]),_:1}),l[23]||(l[23]=i("）。這樣一來，參與者會知道你在評估他們時重視什麼。這也是我們在 HackerOne 提高提交質量的一種方式。",-1))])]),a("p",null,[l[28]||(l[28]=i("另一方面，有些人可能認為競爭被高估了。如果你的目標是鼓勵參與，那麼你有權獎勵每一個參與者，只因他們為社區的回饋！",-1)),r(t,{href:"https://hacktoberfest.com/"},{default:e(()=>[...l[27]||(l[27]=[i("Hacktoberfest",-1)])]),_:1}),l[29]||(l[29]=i(" 就是這種方法的一個好例子。",-1))]),l[47]||(l[47]=n('<h3 id="_8、準備炫酷的禮品" tabindex="-1">8、準備炫酷的禮品 <a class="header-anchor" href="#_8、準備炫酷的禮品" aria-label="Permalink to “8、準備炫酷的禮品”">​</a></h3><p>每個人都喜歡炫酷的禮品！無論是在線活動還是線下活動，你的參與者肯定會欣然接受能夠紀念這次活動的禮品。禮品有兩個目的：</p><ul><li>禮品表示你對參與者的讚賞：貢獻者花費時間投入在與你的緊密合作中，用一份禮品感謝他們就顯示出了你對他們貢獻的價值認同。</li><li>禮品增加了知名度：給參與者分發禮品，幫助他們傳播他們對於社區的喜愛，並通過分享他們的收穫和經驗，提升你的社區的認知度。</li></ul><p>社區成員喜愛禮品，但他們不喜歡單調的禮品！也許你在其他活動中已經發放過你現有的 T 恤和貼紙了。想讓你的黑客馬拉松給人留下深刻印象，就需要尋找新的、有趣的、專有的設計。T 恤固然好，但衞衣則更勝一籌。但是，你可以考慮一下參與者可能還沒有的獨特禮品。想像一下有什麼可以成為他們的新寵，比如後備電池或帽子（這兩樣在 HackerOne 很流行）。對我個人來説，我家裏就有一些來自黑客馬拉松的毛巾和拖鞋！</p><h3 id="_9、進行宣傳" tabindex="-1">9、進行宣傳 <a class="header-anchor" href="#_9、進行宣傳" aria-label="Permalink to “9、進行宣傳”">​</a></h3><p>設定目標和決定驚人的大獎和炫酷的禮品都是非常重要的步驟。但如果你不進行廣泛的宣傳，怎麼能讓人們知道你的黑客馬拉松正在進行呢？你需要仔細調查可用的各類渠道，並要大膽地推廣你的活動。這裏説的包括Blog、視頻Blog、電子郵件、社交媒體 —— 任何你能夠利用的平台。</p><p>然而，依據你的目標定位，你需要在適當的渠道上進行投入。你進行廣告的地方，取決於你想邀請誰來參加你的黑客馬拉松。</p><ul><li>如果你想吸引更有經驗的用户，那麼就將重點放在正在使用你的項目的大型組織上。在這種情況下，領英和電子郵件推廣可能會更有效。</li><li>如果你希望吸引新的和經驗較少的用户，那麼你最好瞄準大學和培訓營。在基於社區的媒體上宣傳活動，如 Mastodon、Matrix、Mattermost、Reddit、Discourse、Discord，以及你的目標聽眾常去的任何地方，將是更好的選擇。</li></ul><h3 id="_10、後期管理" tabindex="-1">10、後期管理 <a class="header-anchor" href="#_10、後期管理" aria-label="Permalink to “10、後期管理”">​</a></h3><p>恭喜，黑客馬拉松結束了！現在所有與黑客馬拉松相關的活動都可以暫時停下，我們也不再需要投入資源了，對嗎？錯！你要把黑客馬拉松視為你在軟件開發和社區構建一系列活動中的一個環節。為了讓你的黑客馬拉松成功，你必須準備好進行活動後的各項工作。</p><ul><li>傳達你的成果：別忘了向內部和外部通報黑客馬拉松的結果。在黑客馬拉松期間，社區成員獲取的成果可以增加對你的社區和項目的信任。</li><li>社區建設：依賴你的黑客馬拉松參與者進行未來的社區活動。</li><li>編制回顧：什麼做得好，什麼做得糟糕，哪些事情讓你感到平淡無奇，又有什麼事情讓你感到驚訝？這個分析是你如何成長，變化和迭代的方式。在可能的情況下，儘快做一個無責任的回顧，這樣所有的事情還鮮活在你的記憶裏。</li></ul><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如果你一開始讀這篇文章時，認為舉辦黑客馬拉松並不難，那麼我很遺憾要打破你的幻想！雖然我深信黑客馬拉松是一個極好的方式，可以在多個層面上與社區進行交流和互動，但只有意圖並不能保證結果。</p><p>為了使一個黑客馬拉松成功，你需要非常周到，並準備投入大量的資源和努力來妥善規劃和執行。</p><p>感謝你的閲讀，我希望這個清單能幫助你成功地組織你的下一場黑客馬拉松！</p><p><em>（題圖：MJ/954f2da1-8a3a-4039-9695-b7ea7e3dea95）</em></p><hr>',17)),a("p",null,[l[31]||(l[31]=i("via: ",-1)),r(t,{href:"https://opensource.com/article/23/2/hackathon-guide"},{default:e(()=>[...l[30]||(l[30]=[i("https://opensource.com/article/23/2/hackathon-guide",-1)])]),_:1})]),a("p",null,[l[35]||(l[35]=i("作者：",-1)),r(t,{href:"https://opensource.com/users/tiffany-long"},{default:e(()=>[...l[32]||(l[32]=[i("Tiffany Long",-1)])]),_:1}),l[36]||(l[36]=i(" 選題：",-1)),r(t,{href:"https://github.com/lkxed/"},{default:e(()=>[...l[33]||(l[33]=[i("lkxed",-1)])]),_:1}),l[37]||(l[37]=i(" 譯者：ChatGPT 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:e(()=>[...l[34]||(l[34]=[i("wxy",-1)])]),_:1})]),a("p",null,[l[40]||(l[40]=i("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...l[38]||(l[38]=[i("LCTT",-1)])]),_:1}),l[41]||(l[41]=i(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:e(()=>[...l[39]||(l[39]=[i("Linux中國",-1)])]),_:1}),l[42]||(l[42]=i(" 榮譽推出",-1))])])}const C=o(d,[["render",h]]);export{P as __pageData,C as default};
